const axios = require('axios');

const API_BASE_URL = 'http://localhost:3001/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

async function testBlogs() {
  console.log('Testing blog API integration...');
  try {
    const response = await api.get('/blogs');
    console.log('Status:', response.status);
    console.log('Response data keys:', Object.keys(response.data));
    console.log('Success:', response.data.success);
    if (response.data.data && response.data.data.blogs) {
      const blogs = response.data.data.blogs;
      console.log('Number of blogs:', blogs.length);
      if (blogs.length > 0) {
        console.log('First blog:', {
          id: blogs[0].id,
          title: blogs[0].title,
          author: blogs[0].author?.name,
          contentLength: blogs[0].content?.length,
        });
      }
    }
    console.log('Integration test PASSED');
    return true;
  } catch (error) {
    console.error('Integration test FAILED:', error.message);
    if (error.response) {
      console.error('Response status:', error.response.status);
      console.error('Response data:', error.response.data);
    }
    return false;
  }
}

async function main() {
  const success = await testBlogs();
  process.exit(success ? 0 : 1);
}

main();

